// Writes src/utils/goUnicode.js from Go's src/unicode/tables.go, the tables
// regexp/syntax reads: \p classes (Categories, Scripts), their case folds
// (FoldCategory, FoldScript) and unicode.SimpleFold's data (asciiFold,
// caseOrbit, CaseRanges). Alertmanager 0.28.1 is built with go1.23.7:
//   curl -sfLO https://raw.githubusercontent.com/golang/go/go1.23.7/src/unicode/tables.go
//   node tests/fixtures/go-regexp/gen-unicode.mjs tables.go
import fs from 'fs'

const src = fs.readFileSync(process.argv[2], 'utf-8')
const version = /^const Version = "([^"]+)"/m.exec(src)[1]
const tables = new Map()
for (const m of src.matchAll(/^var (\w+) = &RangeTable\{\n([\s\S]*?)^\}\n/gm)) {
  const ranges = [...m[2].matchAll(/\{(0x[0-9a-f]+), (0x[0-9a-f]+), (\d+)\}/g)].map(r => [Number(r[1]), Number(r[2]), Number(r[3])])
  tables.set(m[1], ranges)
}
const alias = new Map([...src.matchAll(/^\t(\w+)\s+= (_\w+)\s*(?:\/\/.*)?$/gm)].map(m => [m[1], m[2]]))
const resolve = name => tables.get(name) || tables.get(alias.get(name))
const mapOf = block => {
  const body = new RegExp(`^var ${block} = map\\[string\\]\\*RangeTable\\{\\n([\\s\\S]*?)^\\}`, 'm').exec(src)[1]
  return Object.fromEntries([...body.matchAll(/"(\w+)":\s+(\w+),/g)].map(([, key, name]) => {
    const t = resolve(name)
    if (!t) throw new Error(`no table ${name}`)
    return [key, t]
  }))
}
// A table as text: lo, hi - lo and stride, base 36, deltas from the last hi.
const pack = ranges => {
  let last = 0
  return ranges.map(([lo, hi, s]) => { const out = `${(lo - last).toString(36)}.${(hi - lo).toString(36)}${s === 1 ? '' : `.${s.toString(36)}`}`; last = hi; return out }).join(' ')
}
const packMap = map => `{\n${Object.entries(map).map(([k, v]) => `  ${JSON.stringify(k)}: '${pack(v)}',`).join('\n')}\n}`
const asciiFold = [...new RegExp('^var asciiFold = \\[MaxASCII \\+ 1\\]uint16\\{\\n([\\s\\S]*?)^\\}', 'm').exec(src)[1].matchAll(/0x([0-9A-Fa-f]+)/g)].map(m => parseInt(m[1], 16))
const orbit = [...new RegExp('^var caseOrbit = \\[\\]foldPair\\{\\n([\\s\\S]*?)^\\}', 'm').exec(src)[1].matchAll(/\{0x([0-9A-F]+), 0x([0-9A-F]+)\}/g)].map(m => [parseInt(m[1], 16), parseInt(m[2], 16)])
const UL = 0x10ffff + 1
const caseRanges = [...new RegExp('^var _CaseRanges = \\[\\]CaseRange\\{\\n([\\s\\S]*?)^\\}', 'm').exec(src)[1].matchAll(/\{0x([0-9A-F]+), 0x([0-9A-F]+), d\{([^}]*)\}\}/g)]
  .map(m => [parseInt(m[1], 16), parseInt(m[2], 16), ...m[3].split(',').map(s => (s.trim() === 'UpperLower' ? UL : Number(s.trim())))])

const out = `/*! @license BSD-3-Clause
 * Generated from Go's src/unicode/tables.go (go1.23.7), which is under Go's LICENSE:
 * Copyright (c) 2009 The Go Authors. All rights reserved.
 * Use of this source code is governed by a BSD-style license: Go's LICENSE,
 * in full in public/THIRD_PARTY_NOTICES.md (served with the page). */
// Generated by tests/fixtures/go-regexp/gen-unicode.mjs from Go 1.23.7's
// src/unicode/tables.go (Unicode ${version}): the tables Go's regexp/syntax
// reads, as Alertmanager 0.28.1 is built with. Do not edit.
//
// A table is ranges "lo.span[.stride]" in base 36, lo counted from the last
// range's hi.

export const UNICODE_VERSION = '${version}'
export const CATEGORIES = ${packMap(mapOf('Categories'))}
export const SCRIPTS = ${packMap(mapOf('Scripts'))}
export const FOLD_CATEGORY = ${packMap(mapOf('FoldCategory'))}
export const FOLD_SCRIPT = ${packMap(mapOf('FoldScript'))}
export const ASCII_FOLD = ${JSON.stringify(asciiFold)}
export const CASE_ORBIT = ${JSON.stringify(orbit)}
// [lo, hi, upper, lower, title]; ${UL} is UpperLower.
export const CASE_RANGES = ${JSON.stringify(caseRanges)}
`
fs.writeFileSync(new URL('../../../src/utils/goUnicode.js', import.meta.url), out)
console.log(`wrote src/utils/goUnicode.js: Unicode ${version}, ${Object.keys(mapOf('Categories')).length} categories, ${Object.keys(mapOf('Scripts')).length} scripts, ${caseRanges.length} case ranges, ${orbit.length} orbit pairs, ${out.length} bytes`)
